from html.parser import HTMLParser
from ui import render
class Parsed(HTMLParser):
 def __init__(self,text):
  super().__init__();self.tags=[];self.parts=[];self.headings=[];self.heading=None;self.feed(text)
 def handle_starttag(self,tag,attrs):
  self.tags.append(tag)
  if tag=='h1':self.heading=[]
 def handle_endtag(self,tag):
  if tag=='h1' and self.heading is not None:self.headings.append(' '.join(''.join(self.heading).split()));self.heading=None
 def handle_data(self,data):
  self.parts.append(data)
  if self.heading is not None:self.heading.append(data)
 @property
 def text(self):return ' '.join(''.join(self.parts).split())
first=Parsed(render(True));repeat=Parsed(render(False))
assert first.headings.count('Explore local risk')==1
assert first.text.count('Compare places before you choose.')==1
assert first.text.count('Choose a layer.')==1
assert repeat.text.count('Explore local risk')==0 and repeat.text.count('Compare places before you choose.')==0
assert 'Layers' in first.text and 'Layers' in repeat.text and repeat.text.count('Choose a layer.')==1
